/**
 * Example routes/web.php:
 * 
 * // Protect entire resource with single permission
 * Route::middleware(['auth', 'can:sales_order.view'])->group(function () {
 *     Route::get('/sales-order', [SalesOrderController::class, 'index']);
 * });
 * 
 * // Protect with create permission
 * Route::post('/sales-order', [SalesOrderController::class, 'store'])
 *     ->middleware('can:sales_order.create');
 * 
 * // Protect with multiple permissions (user must have ALL)
 * Route::put('/sales-order/{id}', [SalesOrderController::class, 'update'])
 *     ->middleware(['can:sales_order.edit', 'can:sales_order.view']);
 * 
 * // Protect with role
 * Route::get('/admin/settings', [SettingsController::class, 'index'])
 *     ->middleware('role:admin|super_admin');
 */

// ============================================================================
// BEST PRACTICES
// ============================================================================

/**
 * BEST PRACTICES for implementing permissions:
 * 
 * 1. NAMING CONSISTENCY
 *    - Always use the exact permission name from this file
 *    - Don't create custom permission names
 *    - Use dot notation (module.action)
 * 
 * 2. CONTROLLER CHECKS
 *    - Check permissions in controller methods, not routes
 *    - Use consistent pattern in all controllers
 *    - Check should be first thing in method
 * 
 * 3. BLADE TEMPLATES
 *    - Use @can() directives for better readability
 *    - Always check permissions before showing edit/delete buttons
 *    - Hide forms entirely if user lacks permission
 * 
 * 4. ERROR HANDLING
 *    - Use abort(403) for permission denied
 *    - Show clear error message to user
 *    - Log unauthorized access attempts
 * 
 * 5. ROLE ASSIGNMENT
 *    - Use role_id column in users table for base role
 *    - Use direct permissions for exceptions only
 *    - Document why users have exceptions
 * 
 * 6. TESTING
 *    - Test with different roles
 *    - Verify denied access returns 403
 *    - Test permission transitions
 */

